public function total(string $unit): float
{
    $realUnit = $unit = strtolower($unit);

    if (\in_array($unit, ['days', 'weeks'])) {
        $realUnit = 'dayz';
    } elseif (!\in_array($unit, ['microseconds', 'milliseconds', 'seconds', 'minutes', 'hours', 'dayz', 'months', 'years'])) {
        throw new UnknownUnitException($unit);
    }

    $this->checkStartAndEnd();

    if ($this->startDate && $this->endDate) {
        return $this->totalFromDateRange($unit);
    }

    $result = 0;
    $cumulativeFactor = 0;
    $unitFound = false;
    $factors = self::getFlipCascadeFactors();
    $daysPerWeek = (int) static::getDaysPerWeek();

    $values = [
        'years' => $this->years,
        'months' => $this->months,
        'weeks' => (int) ($this->d / $daysPerWeek),
        'dayz' => fmod($this->d, $daysPerWeek),
        'hours' => $this->hours,
        'minutes' => $this->minutes,
        'seconds' => $this->seconds,
        'milliseconds' => (int) ($this->microseconds / Carbon::MICROSECONDS_PER_MILLISECOND),
        'microseconds' => $this->microseconds % Carbon::MICROSECONDS_PER_MILLISECOND,
    ];

    if (isset($factors['dayz']) && $factors['dayz'][0] !== 'weeks') {
        $values['dayz'] += $values['weeks'] * $daysPerWeek;
        $values['weeks'] = 0;
    }

    foreach ($factors as $source => [$target, $factor]) {
        if ($source === $realUnit) {
            $unitFound = true;
            $value = $values[$source];
            $result += $value;
            $cumulativeFactor = 1;
        }

        if ($factor === false) {
            if ($unitFound) {
                break;
            }

            $result = 0;
            $cumulativeFactor = 0;

            continue;
        }

        if ($target === $realUnit) {
            $unitFound = true;
        }

        if ($cumulativeFactor) {
            $cumulativeFactor *= $factor;
            $result += $values[$target] * $cumulativeFactor;

            continue;
        }

        $value = $values[$source];

        $result = ($result + $value) / $factor;
    }

    if (isset($target) && !$cumulativeFactor) {
        $result += $values[$target];
    }

    if (!$unitFound) {
        throw new UnitNotConfiguredException($unit);
    }

    if ($this->invert) {
        $result *= self::NEGATIVE;
    }

    if ($unit === 'weeks') {
        $result /= $daysPerWeek;
    }

    // Cast as int numbers with no decimal part
    return fmod($result, 1) === 0.0 ? (int) $result : $result;
}

/**
 * Convert the stored date range into a total for the given unit.
 */
private function totalFromDateRange(string $unit): float
{
    $start = $this->startDate;
    $end = $this->endDate;

    if (!\in_array($unit, ['microseconds', 'milliseconds', 'seconds', 'minutes', 'hours'], true)) {
        return $start->diffInUnit($unit, $end);
    }

    if (
        $start->timezoneName !== $end->timezoneName
        || $start->offset !== $end->offset
        || $start->dst !== $end->dst
    ) {
        $start = $start->avoidMutation()->utc();
        $end = $end->avoidMutation()->utc();
    }

    $microseconds = ($end->timestamp - $start->timestamp) * Carbon::MICROSECONDS_PER_SECOND
        + $end->micro - $start->micro;

    return match ($unit) {
        'milliseconds' => $microseconds / Carbon::MICROSECONDS_PER_MILLISECOND,
        'seconds' => $microseconds / Carbon::MICROSECONDS_PER_SECOND,
        'minutes' => $microseconds / (Carbon::MICROSECONDS_PER_SECOND * Carbon::SECONDS_PER_MINUTE),
        'hours' => $microseconds / (
            Carbon::MICROSECONDS_PER_SECOND * Carbon::SECONDS_PER_MINUTE * Carbon::MINUTES_PER_HOUR
        ),
        default => $microseconds,
    };
}

